FTCMAIL = ('FTC: Mail, Internet, or Telephone Order Merchandise Rule', 'https://www.ftc.gov/business-guidance/resources/business-guide-ftcs-mail-internet-or-telephone-order-merchandise-rule')
FTCREV = ('FTC: Rule on the use of consumer reviews and testimonials', 'https://www.ftc.gov/business-guidance/resources/consumer-reviews-testimonials-rule-questions-answers')


def link(s):
    return f'<a href="{s[1]}" target="_blank" rel="noopener">{s[0]}</a>'


def sources(*ss):
    return '<ul>' + ''.join(f'<li>{link(s)}</li>' for s in ss) + '</ul>'


class T:
    def __init__(self):
        self.sections, self.order = {}, []

    def add(self, key, typ, settings=None, blocks=None):
        d = {'type': typ, 'settings': settings or {}}
        if blocks is not None:
            d['blocks'], d['block_order'] = {}, []
            for i, (bt, bs) in enumerate(blocks):
                bid = f'{key}_{i + 1}'
                d['blocks'][bid] = {'type': bt, 'settings': bs}
                d['block_order'].append(bid)
        self.sections[key] = d
        self.order.append(key)
        return self

    def write(self, name, header='US English storefront (V2.1). Seed generated by tools/content/build_us_templates.py; edit in the theme editor.'):
        p = os.path.join(THEME, 'templates', name + '.json')
        with open(p, 'w', encoding='utf-8') as f:
            f.write('/*\n * ' + header + '\n */\n' + json.dumps({'sections': self.sections, 'order': self.order}, indent=2, ensure_ascii=False) + '\n')


def header(t, lead, review='', scheme='scheme-2', heading=''):
    t.add('header', 'ds-page-header', {'color_scheme': scheme, 'heading': heading, 'lead': lead, 'review': review, 'show_review_date': True})


