    C = lambda h, txt, v='all': ('clause', {'heading': h, 'text': txt, 'visible_in': v})

    def legal(name, lead, clauses, identity=True, refs=None):
        t = T()
        header(t, lead, 'juridica', 'scheme-3')
        if name in ('page.shipping', 'page.returns'):
            t.add('summary', 'ds-offer-strip', {'visible_in': 'comercial', 'heading': 'Summary', 'color_scheme': 'scheme-2'})
        t.add('legal', 'ds-legal', {'show_notice': True, 'show_identity': identity}, clauses)
        if refs:
            t.add('sources', 'ds-content', {'show_toc': False, 'padding_top': 0}, [('sources', {'title': 'References for the legal review', 'text': sources(*refs)})])
        t.write(name)

